import { CATEGORIES, type Category, type Difficulty, type QuestionRecord } from "@/lib/domain";

interface SeedText {
  prompt: string;
  answer: string;
  aliases?: string[];
  explanation: string;
  source?: string | null;
}

let counter = 0;

function q(category: Category, difficulty: Difficulty, en: SeedText, tr: SeedText): QuestionRecord {
  counter += 1;
  const id = `q${String(counter).padStart(3, "0")}`;
  return {
    id,
    category,
    difficulty,
    approved: true,
    translations: {
      en: {
        prompt: en.prompt,
        answer: en.answer,
        aliases: en.aliases ?? [],
        explanation: en.explanation,
        source: en.source ?? null,
        language: "en",
      },
      tr: {
        prompt: tr.prompt,
        answer: tr.answer,
        aliases: tr.aliases ?? [],
        explanation: tr.explanation,
        source: tr.source ?? en.source ?? null,
        language: "tr",
      },
    },
  };
}

type WordEntry = [answer: string, enMeaning: string, trMeaning: string, aliases?: string[]];

const DIFFICULTY_CYCLE = ["easy", "medium", "hard"] as const;

function englishWords(category: Category, entries: WordEntry[]): QuestionRecord[] {
  return entries.map(([answer, enMeaning, trMeaning, aliases], index) =>
    q(
      category,
      DIFFICULTY_CYCLE[index % DIFFICULTY_CYCLE.length],
      {
        prompt: `Which word means "${enMeaning}"?`,
        answer,
        aliases: aliases ?? [],
        explanation: `"${answer}" means ${enMeaning}.`,
      },
      {
        prompt: `Hangisi "${trMeaning}" anlamına gelen İngilizce kelimedir?`,
        answer,
        aliases: aliases ?? [],
        explanation: `"${answer}" İngilizcede ${trMeaning} anlamına gelir.`,
      },
    ),
  );
}

function turkishWords(category: Category, difficulty: Difficulty, entries: WordEntry[]): QuestionRecord[] {
  return entries.map(([answer, enMeaning, trMeaning, aliases]) =>
    q(
      category,
      difficulty,
      {
        prompt: `Which Turkish word means "${enMeaning}"?`,
        answer,
        aliases: aliases ?? [],
        explanation: `"${answer}" is Turkish for ${enMeaning}.`,
      },
      {
        prompt: `Hangisi "${trMeaning}" anlamına gelen Türkçe kelimedir?`,
        answer,
        aliases: aliases ?? [],
        explanation: `"${answer}" ${trMeaning} anlamına gelir.`,
      },
    ),
  );
}

