export const QUESTION_SEED = buildQuestions();

export function questionCountByCategory(): Array<{ category: Category; count: number }> {
  return CATEGORIES.map((category) => ({
    category,
    count: QUESTION_SEED.filter((question) => question.category === category).length,
  }));
}
